-- padding blocked_complex fixture=094 line=10080 nested_layers=10 source=full_sql_fixture
WITH q01 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM orders),
q02 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q01 WHERE amount >= 0 OR status IS NOT NULL),
q03 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q02 WHERE amount >= 0 OR status IS NOT NULL),
q04 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q03 WHERE amount >= 0 OR status IS NOT NULL),
q05 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q04 WHERE amount >= 0 OR status IS NOT NULL),
q06 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q05 WHERE amount >= 0 OR status IS NOT NULL),
q07 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q06 WHERE amount >= 0 OR status IS NOT NULL),
q08 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q07 WHERE amount >= 0 OR status IS NOT NULL),
q09 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q08 WHERE amount >= 0 OR status IS NOT NULL),
q10 AS (SELECT customer_id, product_id, shop_id, amount, order_date, dt, region, status FROM q09 WHERE amount >= 0 OR status IS NOT NULL)
SELECT customer_id, APPROX_PERCENTILE(amount, 0.95) AS p95_amount,
ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC) AS rn
FROM q10 WHERE EXISTS (SELECT 1 FROM customers c WHERE c.customer_id = q10.customer_id)
GROUP BY customer_id, amount;
